/// <summary>
/// Extension of table WrkCtrResourceGroup
/// </summary>
[ExtensionOf(tableStr(WrkCtrResourceGroup))]
final public class AVAWrkCtrResourceGroupDbt_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method validateField
/// </summary>
/// <param name = "_fieldIdToCheck">FieldId</param>
/// <returns>boolean</returns>
public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret = next validateField(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(WrkCtrResourceGroup, KCS_NotActiveWrkCtr):
            if(this.KCS_NotActiveWrkCtr == NoYes::Yes)
            {
                ret = ret && !this.avaWrkCtrIdIsUsed();
            }
            break;
    }

    return ret;
}

/// <summary>
/// extension of modifiedField method
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(WrkCtrResourceGroup, KCS_NotActiveWrkCtr):
            if(this.KCS_NotActiveWrkCtr == NoYes::Yes)
            {
                this.NDX_InactiveSince = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            }
            else
            {
                this.NDX_InactiveSince = dateNull();
            }
            break;
    }
}

/// <summary>
///    Performs a form lookup for a resource group name with added range.
///    Otherwise copied from original lookupWrkCtrId method
/// </summary>
/// <param name="_callingControl">
///    An instance of the <c>FormControl</c> class to which the lookup should bind.
/// </param>
/// <param name="_siteId">
///    A <c>SiteId</c> extended data type value with which to filter the lookup data.
/// </param>
/// <param name="_prodUnitId">
///    A <c>ProdUnitId</c> extended data type value with which to filter the lookup data.
/// </param>
/// <param name="_filterByWorkCell">
///    A Boolean value that indicates whether to only filter for work cells.
/// </param>
/// <returns>
///    The record stored in a reference control; otherwise, null.
/// </returns>
public static Common avaLookupWrkCtrId(
    FormControl     _callingControl,
    InventSiteId    _siteId = '',
    ProdUnitId      _prodUnitId = '',
    boolean         _filterByWorkCell = false)
{
    Common                      result = null;

    SysTableLookup              sysTableLookup;
    SysReferenceTableLookup     sysReferenceTableLookup;
    Query                       query               = new Query();
    QueryBuildDataSource        queryBuildDataSource;
    NoYes                       requiresWorkCellNoYes;

    if (!_callingControl)
    {
        throw(error(strfmt("@SYS137393", Error::wrongUseOfFunction(funcname()))));
    }

    switch (_callingControl.handle())
    {
        case classnum(FormReferenceGroupControl):
            sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tablenum(WrkCtrResourceGroup), _callingControl);
            sysReferenceTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, WrkCtrId));
            sysReferenceTableLookup.addLookupMethod(tablemethodstr(WrkCtrResourceGroup, resourceDescription));
            sysReferenceTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, SiteId));
            sysReferenceTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, ProdUnitId));
            sysReferenceTableLookup.addLookupfield(fieldNum(WrkCtrResourceGroup, KCS_NotActiveWrkCtr));
            break;

        case classnum(FormStringControl):
            sysTableLookup = SysTableLookup::newParameters(tablenum(WrkCtrResourceGroup), _callingControl);
            sysTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, WrkCtrId), true);
            sysTableLookup.addLookupMethod(tablemethodstr(WrkCtrResourceGroup, resourceDescription));
            sysTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, SiteId));
            sysTableLookup.addLookupfield(fieldnum(WrkCtrResourceGroup, ProdUnitId));
            sysTableLookup.addLookupfield(fieldNum(WrkCtrResourceGroup, KCS_NotActiveWrkCtr));
            break;

        default:
            throw(error(strfmt("@SYS137393", Error::wrongUseOfFunction(funcname()))));
    }

    queryBuildDataSource = query.addDataSource(tablenum(WrkCtrResourceGroup));
    queryBuildDataSource.addSortField(fieldnum(WrkCtrResourceGroup,WrkCtrId));

    queryBuildDataSource.addRange(fieldNum(WrkCtrResourceGroup, KCS_NotActiveWrkCtr)).value(queryValue(NoYes::No));

    if (_siteId)
    {
        queryBuildDataSource.addRange(fieldnum(WrkCtrResourceGroup,SiteId)).value(queryValue(_siteId));
    }

    if (_prodUnitId)
    {
        // There is no need to filter on ProdUnitDataAreaId
        queryBuildDataSource.addRange(fieldnum(WrkCtrResourceGroup,ProdUnitId)).value(queryValue(_prodUnitId));
    }

    if (_filterByWorkCell)
    {
        requiresWorkCellNoYes = NoYes::Yes;
    }
    else
    {
        requiresWorkCellNoYes = NoYes::No;
    }
    queryBuildDataSource.addRange(fieldnum(WrkCtrResourceGroup,IsWorkCell)).value(queryValue(requiresWorkCellNoYes));

    switch (_callingControl.handle())
    {
        case classnum(FormReferenceGroupControl):
            sysReferenceTableLookup.parmQuery(query);
            result = sysReferenceTableLookup.performFormLookup();
            break;

        case classnum(FormStringControl):
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
            break;

        default:
            throw(error(strfmt("@SYS137393", Error::wrongUseOfFunction(funcname()))));
    }

    return result;
}

/// <summary>
/// checks if WrkCtrId is used in a RouteVersion or ProdTable
/// </summary>
/// <returns>boolean</returns>
public boolean avaWrkCtrIdIsUsed()
{
    boolean         avaIsUsed = false;
    RouteVersion    avaRouteVersion     = this.avaWrkCtrIdIsUsedInRouteVersion();
    ProdTable       avaProdTable        = this.avaWrkCtrIdIsUsedInProdTable();

    if(avaRouteVersion)
    {
        avaIsUsed = true;
        error(strFmt("@NDX:NXARouteInactiveGroupError", this.WrkCtrId, avaRouteVersion.RouteId));
    }
    else if(avaProdTable)
    {
        avaIsUsed = true;
        error(strFmt("@NDX:NXAProdInactiveGroupError", this.WrkCtrId, avaProdTable.ProdId));
    }

    return avaIsUsed;
}

/// <summary>
/// Returns RouteVersion where WrkCtrId is used
/// </summary>
/// <returns>RouteVersion</returns>
public RouteVersion avaWrkCtrIdIsUsedInRouteVersion()
{
    RouteVersion                            avaRouteVersion;
    RouteOpr                                avaRouteOpr;
    WrkCtrRouteOprActivity                  avaWrkCtrRouteOprActivity;
    WrkCtrActivityRequirement               avaWrkCtrActivityRequirement;
    WrkCtrActivityRequirementSet            avaWrkCtrActivityRequirementSet;
    WrkCtrActivityResourceGroupRequirement  avaWrkCtrActivityResourceGroupRequirement;

    select firstonly avaRouteVersion
        join avaRouteOpr
        join avaWrkCtrRouteOprActivity
        join avaWrkCtrActivityRequirementSet
        join avaWrkCtrActivityRequirement
        join avaWrkCtrActivityResourceGroupRequirement
        where avaRouteVersion.Approved                          == NoYes::Yes
            && (avaRouteVersion.ToDate                              == dateNull()
                || (avaRouteVersion.ToDate                          >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
                && avaRouteVersion.FromDate                         <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())))
            && avaRouteVersion.RouteId      == avaRouteOpr.RouteRelation
            && avaRouteOpr.RouteCode        == RouteAll::Route
            && avaRouteOpr.RecId            == avaWrkCtrRouteOprActivity.RouteOpr
            && avaRouteOpr.DataAreaId       == avaWrkCtrRouteOprActivity.RouteOprDataAreaId
            && avaWrkCtrRouteOprActivity.Activity    == avaWrkCtrActivityRequirementSet.Activity
            && avaWrkCtrActivityRequirementSet.RecId == avaWrkCtrActivityRequirement.ActivityRequirementSet
            && avaWrkCtrActivityRequirement.RecId    == avaWrkCtrActivityResourceGroupRequirement.ActivityRequirement
            && avaWrkCtrActivityResourceGroupRequirement.ResourceGroup == this.RecId;

    return avaRouteVersion;
}

/// <summary>
/// Returns ProdTable where WrkCtrId is used
/// </summary>
/// <returns>ProdTable</returns>
public ProdTable avaWrkCtrIdIsUsedInProdTable()
{
    ProdTable                               avaProdTable;
    WrkCtrProdRouteActivity                 avaWrkCtrProdRouteActivity;
    WrkCtrActivityRequirement               avaWrkCtrActivityRequirement;
    WrkCtrActivityRequirementSet            avaWrkCtrActivityRequirementSet;
    WrkCtrActivityResourceGroupRequirement  avaWrkCtrActivityResourceGroupRequirement;

    select firstonly avaProdTable
        join avaWrkCtrProdRouteActivity
        join avaWrkCtrActivityRequirementSet
        join avaWrkCtrActivityRequirement
        join avaWrkCtrActivityResourceGroupRequirement
        where (avaProdTable.ProdStatus                          == ProdStatus::Created
                || avaProdTable.ProdStatus                          == ProdStatus::CostEstimated
                || avaProdTable.ProdStatus                          == ProdStatus::Scheduled
                || avaProdTable.ProdStatus                          == ProdStatus::Released
                || avaProdTable.ProdStatus                          == ProdStatus::StartedUp)     // -> avaProdStatus.ProdStatus <= ProdStatus::StartedUp     this is not working anymore for extendable Enums
            && avaProdTable.ProdId                           == avaWrkCtrProdRouteActivity.ProdId
            && avaWrkCtrProdRouteActivity.Activity   == avaWrkCtrActivityRequirementSet.Activity
            && avaWrkCtrActivityRequirementSet.RecId == avaWrkCtrActivityRequirement.ActivityRequirementSet
            && avaWrkCtrActivityRequirement.RecId    == avaWrkCtrActivityResourceGroupRequirement.ActivityRequirement
            && avaWrkCtrActivityResourceGroupRequirement.ResourceGroup == this.RecId;

    return avaProdTable;
}
